BEGIN;
SELECT plan(19);
INSERT INTO auth.users(id,email) VALUES
 ('e2600000-0000-4000-8000-000000000001','lifecycle-admin@example.invalid'),
 ('e2600000-0000-4000-8000-000000000002','lifecycle-disabled@example.invalid');
INSERT INTO public.profiles(id,email,full_name,role,account_state) VALUES
 ('e2600000-0000-4000-8000-000000000001','lifecycle-admin@example.invalid','Lifecycle Admin','admin','active'),
 ('e2600000-0000-4000-8000-000000000002','lifecycle-disabled@example.invalid','Disabled Admin','admin','disabled');
INSERT INTO public.courses(id,slug,title,subtitle,category,summary,description,venue,status,published_at,provenance)
VALUES('e2600000-0000-4000-8000-000000000003','lifecycle-course','Lifecycle fixture','Course test subtitle','Training','Fixture summary','Fixture description for admission management','Dhaka','published',now(),' {"class":"B","verified":false,"source":"pgTAP fixture"}');
INSERT INTO public.batches(id,course_id,slug,batch_number,name,start_date,end_date,schedule_description,capacity,fee_poisha,status,venue,accept_applications,provenance) VALUES
 ('e2600000-0000-4000-8000-000000000004','e2600000-0000-4000-8000-000000000003','lifecycle-source',1,'Original batch',current_date+1,current_date+2,'Weekend sessions',10,750000,'upcoming','Dhaka',true,'{"class":"B","verified":false,"source":"pgTAP fixture"}'),
 ('e2600000-0000-4000-8000-000000000005','e2600000-0000-4000-8000-000000000003','lifecycle-destination',2,'Destination batch',current_date+5,current_date+6,'Weekend sessions',1,900000,'upcoming','Dhaka',false,'{"class":"B","verified":false,"source":"pgTAP fixture"}');
SELECT ok(NOT has_function_privilege('authenticated','public.manage_staff_admission_lifecycle(uuid,uuid,timestamptz,text,text,uuid,timestamptz,boolean)','EXECUTE'),'Browser cannot cancel or transfer directly');
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.get_staff_admission_management('e2600000-0000-4000-8000-000000000002','e2600000-0000-4000-8000-000000000009')$$,'42501','STAFF_ENROLLMENT_FORBIDDEN','Inactive staff denied');
SELECT is((SELECT public.create_confirmed_staff_admission('e2600000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4M0-0001','Transfer Fixture','transfer-fixture@example.invalid','01799002601','{}','[]','cash','cash',700000,0,'C26',NULL,false,true,false)->>'ok' FROM public.batches WHERE slug='lifecycle-source'),'true','Staff creates paid admission');
SELECT is((SELECT public.get_staff_admission_management('e2600000-0000-4000-8000-000000000001',id)->'destinations'->0->>'name' FROM public.enrollments WHERE public_ref='LNA-W4M0-0001'),'Destination batch','Staff destination with public intake Off is available');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',id,updated_at,'cancel',' ',NULL,NULL,true) FROM public.enrollments WHERE public_ref='LNA-W4M0-0001'),'INVALID','Blank cancellation reason rejected');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',id,updated_at-interval '1 minute','cancel','Student request',NULL,NULL,true) FROM public.enrollments WHERE public_ref='LNA-W4M0-0001'),'STALE','Stale change denied');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',e.id,e.updated_at,'transfer','Schedule change',b.id,b.updated_at-interval '1 minute',true) FROM public.enrollments e CROSS JOIN public.batches b WHERE e.public_ref='LNA-W4M0-0001' AND b.slug='lifecycle-destination'),'STALE_BATCH','Changed destination fee or settings require reconfirmation');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',e.id,e.updated_at,'transfer','Schedule change',b.id,b.updated_at,true) FROM public.enrollments e CROSS JOIN public.batches b WHERE e.public_ref='LNA-W4M0-0001' AND b.slug='lifecycle-destination'),'OK','Confirmed admission transfers atomically');
SELECT ok((SELECT e.batch_id='e2600000-0000-4000-8000-000000000005' AND e.status='confirmed' AND e.payable_poisha=700000 AND e.submitted_payment_ref='C26' AND e.staff_payment_details->>'original_payable_poisha'='750000' FROM public.enrollments e WHERE e.public_ref='LNA-W4M0-0001'),'Transfer preserves original payment and reference');
SELECT ok(public.count_batch_active_seats('e2600000-0000-4000-8000-000000000004')=0 AND public.count_batch_active_seats('e2600000-0000-4000-8000-000000000005')=1,'Seat moves from source to destination');
SELECT ok((SELECT count(*)=1 FROM public.audit_events WHERE action='staff_transferred_admission' AND actor_id='e2600000-0000-4000-8000-000000000001' AND batch_id='e2600000-0000-4000-8000-000000000004' AND secondary_batch_id='e2600000-0000-4000-8000-000000000005' AND after_state->>'destination_fee_poisha'='900000'),'Transfer history records both batches and fee difference');
SELECT is((SELECT public.create_confirmed_staff_admission('e2600000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4M0-0002','Second Fixture','second-fixture@example.invalid','01799002602','{}','[]','cash','cash',750000,0,'C27',NULL,false,true,false)->>'ok' FROM public.batches WHERE slug='lifecycle-source'),'true','Creates second paid admission');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',e.id,e.updated_at,'transfer','Schedule change',b.id,b.updated_at,true) FROM public.enrollments e CROSS JOIN public.batches b WHERE e.public_ref='LNA-W4M0-0002' AND b.slug='lifecycle-destination'),'BATCH_FULL','Full destination rejected');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',id,updated_at,'cancel','Student request',NULL,NULL,true) FROM public.enrollments WHERE public_ref='LNA-W4M0-0001'),'OK','Staff cancels confirmed paid admission');
SELECT ok((SELECT status='cancelled' AND payment_status='verified' AND payable_poisha=700000 AND confirmed_at IS NOT NULL AND submitted_payment_ref='C26' FROM public.enrollments WHERE public_ref='LNA-W4M0-0001') AND public.count_batch_active_seats('e2600000-0000-4000-8000-000000000005')=0,'Cancellation releases seat but keeps verified collection');
SELECT is(public.start_checked_public_enrollment('lifecycle-course','lifecycle-source','LNA-W4M0-0003','Pending Fixture','pending-fixture@example.invalid','01799002603','{}','[]',NULL,750000,'hosted')->>'ok','true','Hosted checkout attempt created');
SELECT is((SELECT public.manage_staff_admission_lifecycle('e2600000-0000-4000-8000-000000000001',id,updated_at,'cancel','Applicant request',NULL,NULL,true) FROM public.enrollments WHERE public_ref='LNA-W4M0-0003'),'OK','Pending application may be cancelled without deleting the attempt');
SELECT is((SELECT public.confirm_payment(pa.id,'PAY-LIFECYCLE-1','TRX-LIFECYCLE-1',750000,'BDT','0000','Late receipt')->>'reason' FROM public.payment_attempts pa JOIN public.enrollments e ON e.id=pa.enrollment_id WHERE e.public_ref='LNA-W4M0-0003'),'ENROLLMENT_INELIGIBLE','Late payment is retained without reopening the application');
SELECT is((SELECT public.create_confirmed_staff_admission('e2600000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4M0-0004','Pending Fixture','pending-fixture@example.invalid','01799002603','{}','[]','cash','cash',750000,0,'C28',NULL,false,true,false)->>'code' FROM public.batches WHERE slug='lifecycle-source'),'DUPLICATE_ENROLLMENT','Staff cannot collect again with unresolved cancelled payment');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
